export type TicketField = { id: string; label: string; placeholder?: string };
export type TicketType = {
  id: string;
  label: string;
  summary: string;
  detail: string;
  factor: number;
  pieceTypes: string[];
  formats: string[];
  linkLabel: string;
  linkRequired: boolean;
  fields: TicketField[];
};
export type TicketPriority = 'alta' | 'normal';
export type Ticket = {
  id: string;
  type: string;
  typeLabel: string;
  title: string;
  description: string;
  pieceType: string;
  format: string;
  links: string[];
  details: Record<string, string>;
  priority: TicketPriority;
  dueDate: string;
  /** Hora de entrega ("17:00"); ausente nos pedidos antigos (18:00). */
  dueTime?: string;
  /** Expediente em vigor quando o pedido foi feito. */
  schedule?: Schedule;
  leadHours: number;
  effortHours: number;
  businessHours: number;
  requesterName: string;
  requesterEmail: string;
  createdAt: string;
};
export type TicketInput = Partial<Omit<Ticket, 'links' | 'priority'>> & { links?: string[] | string; priority?: string | null };
export type Schedule = { days: number[]; periods: [string, string][]; updatedAt?: string; updatedBy?: string };
export type Interval = { start: number; end: number };
export type CalendarEvent = { summary: string; description: string; startTime: string; endTime: string; timeZone: string };

